 const add=(ingredient,macros)=>{if(rows.length>=100)throw Error('Use up to 100 ingredients per recipe.');const candidate=[...rows,{ingredient,nutrition:macros}];if(mode==='ingredients'&&candidate.every(x=>x.nutrition!==null))recipeIngredientTotals(candidate.map(x=>x.ingredient),candidate.map(x=>x.nutrition));rows=candidate;draw();};
 clearDraft();$('#recipe-yield').value=r.servings;$('#recipe-mode').value=mode;
 const setMode=()=>{mode=$('#recipe-mode').value;$('#recipe-batch-fields').hidden=mode!=='manual';$('#recipe-mode-hint').textContent=mode==='ingredients'?'Batch and per-serving totals update when you add, edit or remove ingredients.':'Manual mode keeps your saved batch totals. Add per-ingredient macros before switching to automatic totals.';preview();};$('#recipe-mode').onchange=()=>{setMode();draw();};setMode();draw();
 $('#recipe-item-amount').onchange=()=>{if(editing===null||!rows[editing].nutrition)return;try{const item=rows[editing],scaled=scaleRecipeIngredientNutrition(item.nutrition,number($('#recipe-item-amount').value,'ingredient amount')/item.ingredient.amount);for(const k of NUTRIENTS)$('#recipe-item-'+k).value=scaled[k];}catch(err){$('#recipe-ingredient-error').textContent=err.message;}};
 $('#recipe-cancel-ingredient').onclick=clearDraft;
 $('#recipe-add-ingredient').onclick=()=>{try{const ingredient={name:$('#recipe-item-name').value.trim(),amount:number($('#recipe-item-amount').value,'ingredient amount'),unit:$('#recipe-item-unit').value.trim()},raw=NUTRIENTS.map(k=>$('#recipe-item-'+k).value),letMacros=mode==='manual'&&raw.every(x=>x==='')?null:validateRecipeIngredientNutrition(Object.fromEntries(NUTRIENTS.map(k=>[k,number($('#recipe-item-'+k).value,k+' for this ingredient')]))),macros=letMacros&&editing!==null&&rows[editing].nutrition?.foodSource?{...letMacros,foodSource:{...rows[editing].nutrition.foodSource,amount:rows[editing].nutrition.foodSource.amount*ingredient.amount/rows[editing].ingredient.amount,manualAdjusted:true}}:letMacros;validateIngredients([ingredient]);if(editing===null)add(ingredient,macros);else{const candidate=rows.map((x,i)=>i===editing?{ingredient,nutrition:macros}:x);if(mode==='ingredients'&&candidate.every(x=>x.nutrition!==null))recipeIngredientTotals(candidate.map(x=>x.ingredient),candidate.map(x=>x.nutrition));rows=candidate;draw();}clearDraft();}catch(err){$('#recipe-ingredient-error').textContent=err.message;}};
 $('#recipe-add-usual').onclick=()=>{try{const choice=$('#recipe-usual').value;if(choice===''||!state.usualFoods[Number(choice)])throw Error('Choose a saved food first.');const food=state.usualFoods[Number(choice)];add({name:food.name,amount:1,unit:'serving'},validateRecipeIngredientNutrition({...Object.fromEntries(NUTRIENTS.map(k=>[k,food[k]])),...(food.foodSource?{foodSource:food.foodSource}:{})}));$('#recipe-usual').value='';$('#recipe-error').textContent='';}catch(err){$('#recipe-error').textContent=err.message;}};
 bindFoodLookup(food=>{if(editing!==null||$('#recipe-item-name').value.trim())throw Error('Add or clear the ingredient you are editing first.');const ingredient=food.ingredients[0];add(ingredient,validateRecipeIngredientNutrition({...Object.fromEntries(NUTRIENTS.map(k=>[k,food[k]])),foodSource:food.foodSource}));},{applyLabel:'Add ingredient to recipe',successText:'Ingredient added. Search for another food to keep building your recipe.'});
