$('#app').addEventListener('change',e=>{if(e.target.closest?.('#settings,#lookup-settings,#backup-reminder,#checkin,#drink-entry,#legacy-water')){dirtyView=true;const status=$('[data-save-status]');if(status)status.textContent='Unsaved changes';}if(e.target.dataset.pantryIndex!==undefined){const item=groceryList(state,planStart).items[Number(e.target.dataset.pantryIndex)];if(!item)return;const key=item.name.toLowerCase(),pantry=new Set(state.pantry);if(e.target.checked)pantry.add(key);else pantry.delete(key);state.pantry=[...pantry];persist();render();}if(e.target.dataset.groceryIndex!==undefined){const item=groceryList(state,planStart).items[Number(e.target.dataset.groceryIndex)];if(!item)return;const checked=new Set(state.groceryChecks[planStart]||[]);if(e.target.checked)checked.add(item.key);else checked.delete(item.key);state.groceryChecks[planStart]=[...checked];persist();render();}});
