const guardedActions=new Set(['nav','section','prev-day','next-day','date-today','open-day','plan-day','plan-prev','plan-next','plan-today','next-week','period','coach-mode','show-today-plan','list-page','edit-drink','delete-drink']);
$('#app').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(dirtyView&&guardedActions.has(b.dataset.action)){confirmDialog('Leave without saving?','Your current form has unsaved changes. Save it first, or confirm to leave this form.',()=>{dirtyView=false;runAction(b).catch(err=>toast(err.message));});return;}try{await runAction(b);}catch(err){toast(err.message);}});
async function runAction(b){const action=b.dataset.action;
if(action==='section'){const next=resolveRoute(b.dataset.group,b.dataset.panel);view=next.view;panels[view]=next.panel;listPages.foods=0;render();window.scrollTo(0,0);}
if(action==='list-page'){const key=b.dataset.list;if(key in listPages){listPages[key]=Math.max(0,Number(b.dataset.page)||0);render();window.scrollTo(0,0);}}
if(action==='clear-filter'){listQueries[b.dataset.list]='';listPages[b.dataset.list]=0;render();}
if(action==='grocery-filter'){if(['buy','all','checked'].includes(b.dataset.filter)){groceryFilter=b.dataset.filter;listPages.groceries=0;render();}}
if(action==='new-usual')mealDialog(null,false,null,true);
if(action==='new-recipe')recipeEditor();
if(action==='use-library'){const source=b.dataset.kind==='recipe'?recipeMeal(state.recipes[Number(b.dataset.index)]):{...state.usualFoods[Number(b.dataset.index)],id:undefined,planMealId:undefined};mealDialog(source,b.dataset.destination==='plan');}
if(action==='edit-library'){const i=Number(b.dataset.index);if(b.dataset.kind==='recipe')recipeEditor(state.recipes[i]);else mealDialog(state.usualFoods[i],false,null,true);}
if(action==='delete-library'){const recipe=b.dataset.kind==='recipe',list=recipe?state.recipes:state.usualFoods,item=list[Number(b.dataset.index)];if(item)confirmDialog(recipe?'Delete recipe?':'Remove usual food?',item.name+'. Existing logged meals stay intact.',()=>{if(recipe)state.recipes=state.recipes.filter(x=>x.id!==item.id);else state.usualFoods=state.usualFoods.filter(x=>x.id!==item.id);persist();render();toast('Library item removed.');});}
if(action==='edit-drink'){const drink=(d().drinks||[]).find(x=>x.id===b.dataset.id);if(drink)drinkDialog(drink);}
if(action==='delete-drink'){const date=selected;confirmDialog('Delete drink?','Remove this serving from hydration and calorie totals?',()=>{const day=state.days[date];day.drinks=(day.drinks||[]).filter(x=>x.id!==b.dataset.id);day.complete=false;persist();render();});}
if(action==='find-food'){openModal(`<h2>Find a food</h2>${foodLookupHTML().replace('<details class="food-lookup">','<details class="food-lookup" open>')}<div class="modal-actions"><button class="btn secondary" data-close>Close</button></div>`);bindFoodLookup(food=>{$('#modal').close();mealDialog(food);});}

if(action==='recipes')recipeDialog();
if(action==='pantry')pantryDialog();
if(action==='swap-plan')swapDialog(b.dataset.date,Number(b.dataset.index));
if(action==='toggle-skip-plan'){const meal=state.plans[b.dataset.date]?.meals[Number(b.dataset.index)];if(meal){meal.skipped=!meal.skipped;persist();render();}}
if(action==='copy-day-stats')await copy(dailyFeedbackPrompt(state,selected));
if(action==='copy-week-review')copy(reviewPrompt(state,selected,'week'));
if(action==='check-update')await checkForUpdate();
if(action==='apply-update'){if(swRegistration?.waiting)swRegistration.waiting.postMessage({type:'SKIP_WAITING'});location.reload();}
if(action==='nav'){if(view==='today'&&b.dataset.view==='plan'&&b.dataset.panel==='meals')planFromToday=true;navigate(b.dataset.view,b.dataset.panel);}
if(action==='prev-day'||action==='next-day'){selected=addDays(selected,action==='prev-day'?-1:1);render();}
if(action==='open-day'){selected=b.dataset.date;navigate('today','food');}
if(action==='date-today'){selected=dateKey();render();}
if(action==='add-meal')mealDialog();
if(action==='edit-meal')mealDialog(d().meals.find(x=>x.id===b.dataset.id));
if(action==='delete-meal')confirmDialog('Remove this food entry?','This removes the serving from this day’s actual food log.',()=>{ensure().meals=d().meals.filter(x=>x.id!==b.dataset.id);ensure().complete=false;persist();render();});
if(action==='training-schedule')trainingDialog();
if(action==='edit-timeline-workout')timelineWorkoutDialog(b.dataset.date,b.dataset.id);
if(action==='edit-timeline-gap')timelineGapDialog(b.dataset.date,b.dataset.from,b.dataset.to);
if(action==='favorites')usualDialog();
if(action==='meal-import')importDialog(b.dataset.destination);
if(action==='show-today-plan'){planDay=selected;planStart=weekStart(selected);view='plan';panels.plan='meals';render();}
if(action==='plan-prev'||action==='plan-next'){planStart=addDays(planStart,action==='plan-prev'?-7:7);planDay=planStart;render();}
if(action==='plan-today'){planDay=dateKey();planStart=weekStart(planDay);render();}
if(action==='next-week'){planStart=nextWeek();planDay=planStart;render();}
if(action==='copy-groceries'){const text=groceryText(groceryList(state,planStart),planStart,addDays(planStart,6));try{await navigator.clipboard.writeText(text);toast('Grocery list copied.');}catch{openModal(`<h2>Copy grocery list</h2><textarea id="grocery-copy" class="prompt-box" style="width:100%" readonly>${esc(text)}</textarea><div class="modal-actions"><button class="btn secondary" data-close>Close</button></div>`);$('#grocery-copy').focus();$('#grocery-copy').select();}}
if(action==='plan-fuel-time'&&['10:00','12:00','15:00','17:00','21:00','22:00'].includes(b.dataset.time)){planFuelTime=b.dataset.time;render();$('#plan-fuel-'+planFuelTime.replace(':','')).focus();}
if(action==='plan-day'){planDay=b.dataset.date;render();}
if(action==='add-plan')mealDialog(null,true);
if(action==='edit-plan-day'){const meals=state.plans[planDay].meals;openModal(`<div class="card-head"><h2>Edit planned meals</h2><button class="btn soft" id="add-planned-usual">Add from Usual foods</button></div>${meals.map((m,i)=>`<div class="meal"><div class="meal-body"><h3>${esc(m.name)}</h3><p>${esc(m.portion)}</p></div><button class="iconbtn" data-plan-edit="${i}" aria-label="Edit ${esc(m.name)}">${icon('edit')}</button><button class="iconbtn" data-plan-delete="${i}" aria-label="Remove ${esc(m.name)}">${icon('trash')}</button></div>`).join('')}<div class="modal-actions"><button class="btn secondary" data-close>Close</button></div>`);$('#add-planned-usual').onclick=()=>{$('#modal').close();mealDialog(null,true);};$('#modal').querySelectorAll('[data-plan-edit]').forEach(x=>x.onclick=()=>{$('#modal').close();mealDialog(meals[Number(x.dataset.planEdit)],true,Number(x.dataset.planEdit));});$('#modal').querySelectorAll('[data-plan-delete]').forEach(x=>x.onclick=()=>{$('#modal').close();confirmDialog('Remove planned meal?','Only the plan will change.',()=>{meals.splice(Number(x.dataset.planDelete),1);persist();render();});});}
if(action==='delete-planned-meal'){const date=b.dataset.date,index=Number(b.dataset.index),meal=state.plans[date]?.meals[index];if(meal)confirmDialog('Delete this planned meal?',meal.name+' will be removed from the plan. Logged food stays intact.',()=>{if(state.plans[date]?.meals[index]!==meal){toast('The plan changed. Reopen the meal before deleting.');return;}state.plans[date].meals.splice(index,1);persist();render();toast('Planned meal deleted.');});}
if(action==='edit-planned-meal'){const date=b.dataset.date,index=Number(b.dataset.index);if(state.plans[date]?.meals[index]){planDay=date;mealDialog(state.plans[date].meals[index],true,index);}}
if(action==='eat-plan'){const date=b.dataset.date,m=state.plans[date].meals[Number(b.dataset.index)];const eat=()=>{const day=state.days[date]??=freshDay(date,state.weeklyTraining);day.meals.push({...m,id:crypto.randomUUID(),planMealId:m.id,skipped:undefined,originalPlan:undefined});day.complete=false;m.skipped=false;day.meals.sort((a,b)=>a.time.localeCompare(b.time));persist();render();toast(`Logged eaten for ${pretty(date)}.`);};const alreadyLogged=!!m.id&&(state.days[date]?.meals||[]).some(entry=>entry.planMealId===m.id);confirmDialog(alreadyLogged?'Log another serving?':'Log this meal as eaten?',`${m.name} · ${m.portion}. ${alreadyLogged?'This meal is already logged. Confirm to add another serving to':'This adds one serving to'} ${pretty(date)}.`,eat);}
if(action==='period'){period=b.dataset.period;listPages.history=0;render();}
if(action==='review-coach'){coachMode='review';coachPrompt=reviewPrompt(state,selected,period);view='coach';render();}
if(action==='plan-coach'){coachMode='plan';coachPrompt=planPrompt(state,planStart);view='coach';render();}
if(action==='copy-review')copy(reviewPrompt(state,selected,period));
if(action==='coach-mode'){navigate('coach',b.dataset.mode);}
if(action==='generate'){try{refreshCoachPrompt();render();toast('Prompt ready to copy.');}catch(err){toast(err.message);}}
if(action==='copy-prompt'){const prompt=refreshCoachPrompt();if($('#prompt-output'))$('#prompt-output').value=prompt;await copy(prompt);}
if(action==='preview-import')previewImport();
if(action==='commit-import'&&draft){const imported=draft;const dates=Object.keys(imported).sort();confirmDialog('Import this reviewed week?',`Replace planned meals for ${pretty(dates[0])} through ${pretty(dates.at(-1))}? Your eaten food and check-ins stay separate.`,()=>{for(const k of dates)state.plans[k]={...imported[k],meals:imported[k].meals.map(m=>({...m,id:crypto.randomUUID()}))};persist();draft=null;planDay=dates[0];planStart=dates[0];view='plan';panels.plan='meals';importText='';render();toast('Meal plan imported.');});}
if(action==='export')exportBackup();
if(action==='restore')$('#backup-file').click();
if(action==='install'&&installEvent){await installEvent.prompt();installEvent=null;render();}
}
