window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;if(view==='settings'&&!dirtyView)render();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){if(dirtyView){try{state=validateBackup(JSON.parse(e.newValue));toast('Updated data from another tab; your unsaved form is still here.');}catch{toast('Could not read an update from another tab.');}return;}try{state=validateBackup(JSON.parse(e.newValue));render();toast('Updated from another tab.');}catch{toast('Could not read an update from another tab.');}}});
