const revealInvalid=e=>{let detail=e.target?.closest?.('details');while(detail){detail.open=true;detail=detail.parentElement?.closest?.('details');}};
$('#app').addEventListener('invalid',revealInvalid,true);$('#modal').addEventListener('invalid',revealInvalid,true);
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',applyTheme);
async function checkForUpdate(){if(!('serviceWorker' in navigator)){updateStatus='Updates are available after refreshing this page online.';if(view==='settings'&&!dirtyView)render();return;}updateStatus='Checking for an update…';if(view==='settings'&&!dirtyView)render();try{swRegistration=swRegistration||await navigator.serviceWorker.getRegistration();if(!swRegistration)throw Error('Open once online to register the offline app.');await swRegistration.update();updateAvailable=!!swRegistration.waiting;const response=await fetch('./version.json',{cache:'no-store'});if(response.ok){const latest=await response.json();updateAvailable=updateAvailable||latest.version!=='2.12.1';}updateStatus=updateAvailable?'An update is available. Save open edits, then reload.':'You are up to date · v2.12.1.';}catch(err){updateStatus='Unable to check while offline. Your saved app remains available.';}if(view==='settings'&&!dirtyView)render();}
render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(registration=>{swRegistration=registration;updateAvailable=!!registration.waiting;registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){updateAvailable=true;updateStatus='Update available. Save open edits, then reload.';if(view==='settings'&&!dirtyView)render();else toast('Update available · open Settings to reload.');}});});}).catch(()=>{});

function refreshVisibleFuelTimeline(){const region=$('#fuel-timeline-region');if(view==='today'&&panels.today==='training'&&!dirtyView&&!$('#modal').open&&region&&!region.querySelector('.swipe-open,.swipe-dragging'))region.innerHTML=timelineHTML(selected);}
window.setInterval?.(refreshVisibleFuelTimeline,60000);
document.addEventListener?.('visibilitychange',()=>{if(!document.hidden)refreshVisibleFuelTimeline();});
